Given two arrays a[] and b[] with distinct elements, the task is to return union of both the arrays in any order. Note: Union of two arrays is an array having all distinct elements that are present in either array.Examples:Input: a[] = {1, 2, 3}, b[] = {5, 2, 7}Output: {1, 2, 3, 5, 7}Explanation: 1, 2, 3, 5 and 7 are the distinct elements present in either array.Input: a[] = {2, 4, 5}, b[] = {1, 2, 3, 4, 5}Output: {1, 2, 3, 4, 5}Explanation: 1, 2, 3, 4 and 5 are the distinct elements present in either array.Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n * m) Time and O(1) Space[Expected Approach] Using Hash Set - O(n + m) Time and O(n + m) Space[Naive Approach] Using Nested Loops - O(n * m) Time and O(1) SpaceThe idea is to add all elements from the first array a[] to a result array. Then iterate through the second array b[] and add its elements to the result only if they were not present in a[]. This ensures that all the elements from both arrays are included, with no duplicates.
            C++

    // C++ program to find union of two arrays
// with distinct elements

#include <iostream>
#include <vector>
using namespace std;

vector<int> findUnion(vector<int> &a, vector<int> &b) {
    vector<int> res = a;

    // Traverse through b[] and search every element
    // b[i] in a[]
    for (int i = 0; i < b.size(); i++) {

        // check if the element was present in a[]
        // to avoid duplicates
        int j;
        for (j = 0; j < a.size(); j++) {
            if (a[j] == b[i])
                break;
        }

        // if not already present then
        // add it to result
        if (j == a.size()) {
            res.push_back(b[i]);
        }
    }
    return res;
}

int main() {

    vector<int> a = {1, 2, 3};
    vector<int> b = {5, 2, 7};

    vector<int> res = findUnion(a, b);

    for (int i = 0; i < res.size(); i++)
        cout << res[i] << " ";

    return 0;
}


